import { jsx as _jsx } from "react/jsx-runtime";
import path from 'path';
import { CMD_EXEC_PATH, NEXT_PROPS_PATH, PREVIEW_PATH } from '../../constants.js';
import { addChangeLog, addErrorLog, getCurrentErrorLogs, removeErrorLogs, } from '../../logging-state.js';
import { ErrorLog, InfoLog, SuccessLog, WarningLog } from '../../logs.js';
import { regenerateAllSnippets } from '../listener/regenerateAllSnippets.js';
import { PackagesDev } from './dev.js';
import { createPackageRoute, PACKAGE_ROUTE_PREFIX } from './serve.js';
const MAX_LOGGED = 5;
let instance;
let shownIslandErrors = { key: '', logs: [] };
const reporter = {
    building: () => {
        addChangeLog(_jsx(InfoLog, { message: "building npm packages\u2026" }));
    },
    built: ({ buildId, islands, ms, warnings }) => {
        addChangeLog(_jsx(SuccessLog, { message: `built npm packages (${islands} component${islands === 1 ? '' : 's'}, build ${buildId.slice(0, 12)}) in ${(ms / 1000).toFixed(1)}s` }));
        for (const warning of warnings.slice(0, MAX_LOGGED)) {
            addChangeLog(_jsx(WarningLog, { message: `npm packages: ${warning}` }));
        }
    },
    failed: (errors, warnings) => {
        for (const error of errors.slice(0, MAX_LOGGED)) {
            addErrorLog(_jsx(ErrorLog, { message: `npm packages: ${error}` }));
        }
        for (const warning of warnings.slice(0, MAX_LOGGED)) {
            addChangeLog(_jsx(WarningLog, { message: `npm packages: ${warning}` }));
        }
    },
    missingNodeModules: (docsRoot) => {
        addErrorLog(_jsx(ErrorLog, { message: `docs.json uses npm packages but ${path.join(docsRoot, 'node_modules')} is missing. Run npm install --ignore-scripts in ${docsRoot}; package components stay empty until then.` }));
    },
    configError: (message) => {
        addErrorLog(_jsx(ErrorLog, { message: `npm packages: ${message}` }));
    },
    islandErrors: (errors) => {
        const key = errors.join('\n');
        const current = getCurrentErrorLogs();
        const visible = shownIslandErrors.logs.every((log) => current.includes(log));
        if (key === shownIslandErrors.key && visible)
            return;
        removeErrorLogs(shownIslandErrors.logs);
        const logs = errors
            .slice(0, MAX_LOGGED)
            .map((error) => _jsx(ErrorLog, { message: `npm packages: ${error}` }));
        logs.forEach(addErrorLog);
        shownIslandErrors = { key, logs };
    },
};
const onRebuiltRef = { current: () => { } };
export const setPackagesRebuiltListener = (listener) => {
    onRebuiltRef.current = listener;
};
const reportError = (error) => addErrorLog(_jsx(ErrorLog, { message: `npm packages: ${error instanceof Error ? error.message : String(error)}` }));
export const startPackagesDev = async () => {
    await instance?.close();
    instance = new PackagesDev({
        docsRoot: CMD_EXEC_PATH,
        buildsDir: path.join(PREVIEW_PATH, 'packages'),
        propsPath: NEXT_PROPS_PATH,
        onRebuilt: () => onRebuiltRef.current(),
        regenerateSnippets: regenerateAllSnippets,
        reporter,
    });
    try {
        await instance.init();
    }
    catch (error) {
        reportError(error);
    }
};
export const notifyPackageInputChange = async (filename, category) => {
    try {
        await instance?.onFileChange(filename, category);
    }
    catch (error) {
        reportError(error);
    }
};
export const writePackageBuildProps = async () => {
    await instance?.writeProps();
};
export const packageRoute = {
    prefix: PACKAGE_ROUTE_PREFIX,
    handler: createPackageRoute(() => instance?.routeState() ?? {
        enabled: false,
        buildsDir: '',
    }),
};
